mapper.select:
SELECT DISTINCT m.perms FROM sys_menu m LEFT JOIN sys_role_menu rm ON m.menu_id = rm.menu_id JOIN sys_role r ON r.role_id = rm.role_id AND r.status = 1 AND r.is_deleted=0 WHERE rm.role_id IN
#{roleId}
AND m.perms IS NOT NULL AND m.perms != '' AND m.status = '0' AND m.is_deleted=0 UNION SELECT nav.perms FROM sys_menu nav WHERE nav.perms='ai:monitor:enter' AND nav.status='0' AND nav.is_deleted=0 AND EXISTS ( SELECT 1 FROM sys_role_menu granted_action JOIN sys_role active_role ON active_role.role_id=granted_action.role_id AND active_role.status=1 AND active_role.is_deleted=0 JOIN sys_menu action_menu ON action_menu.menu_id=granted_action.menu_id AND action_menu.status='0' AND action_menu.is_deleted=0 WHERE granted_action.role_id IN
#{roleId}
AND action_menu.perms IN ('ai:scene:invoke','ai:request:list','ai:config:list','ai:config:query','ai:config:add','ai:config:edit','ai:config:test','ai:config:enable') )
